def choose_move(observation):
    wx, wy = observation['grid_width'], observation['grid_height']
    me_x, me_y = observation['self_position']
    resources = observation['resources']
    obstacles = observation['obstacles']
    opponent_x, opponent_y = observation['opponent_position']
    score_self, score_opponent = observation['scores']
    self_path = set(observation['self_path'])
    opponent_path = set(observation['opponent_path'])

    def is_blocked(x, y):
        if x < 0 or y < 0 or x >= wx or y >= wy:
            return True
        if (x, y) in obstacles:
            return True
        if (x, y) in self_path or (x, y) in opponent_path:
            return True
        return False

    # Try to move towards nearest resource
    if resources:
        res = min(resources, key=lambda r: abs(r['x'] - me_x) + abs(r['y'] - me_y))
        dx = (res['x'] > me_x) - (res['x'] < me_x)
        dy = (res['y'] > me_y) - (res['y'] < me_y)
        if not is_blocked(me_x + dx, me_y + dy):
            return [dx, dy]
    # Else, move away from opponent if close
    dist_opponent = abs(opponent_x - me_x) + abs(opponent_y - me_y)
    if dist_opponent <= 2:
        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
            nx, ny = me_x + dx, me_y + dy
            if not is_blocked(nx, ny):
                if abs(opponent_x - nx) + abs(opponent_y - ny) > dist_opponent:
                    return [dx, dy]
    # Otherwise, move randomly or stay
    for dx, dy in [(-1,0),(1,0),(0,-1),(0,1),(0,0)]:
        nx, ny = me_x + dx, me_y + dy
        if not is_blocked(nx, ny):
            return [dx, dy]
    return [0, 0]
